def _participant_fields_from_draft_obj(obj: Mapping[str, Any]) -> Dict[str, Any]:
    """从抽取原包收承办人/参与人——拟旨意图=无时仍可后置点将（#1778）。"""
    out: Dict[str, Any] = {}
    if "承办人" in obj or "assignee" in obj or "assignee_name" in obj:
        out["assignee"] = str(
            obj.get("承办人") or obj.get("assignee") or obj.get("assignee_name") or ""
        ).strip()
    if "参与人" in obj:
        out["participant_roster"] = obj.get("参与人") if obj.get("参与人") is not None else []
    elif "participant_roster" in obj:
        out["participant_roster"] = obj.get("participant_roster")
    return out

def _resolve_unique_active_authority(
    db: Any,
    turn: int,
    *,
    authority_id: object = 0,
    holder_id: object = "",
    privilege: object = "",
) -> Optional[Dict[str, Any]]:
    """候选层：自然语言/结构字段唯一解析到现存在持 authority_records 行。

    0/多条 → None（不得发生产项）。显式 authority_id 优先。
    """
    holder = str(holder_id or "").strip()
    priv = str(privilege or "").strip()
    if priv in {"", "无"}:
        priv = ""
    try:
        aid = int(authority_id or 0)
    except (TypeError, ValueError):
        aid = 0
    if aid > 0:
        rec = db.get_authority(aid)
        if rec is None or bool(rec.get("revoked")):
            return None
        try:
            effective = int(rec.get("effective_turn") or 0)
        except (TypeError, ValueError):
            effective = 0
        if effective > int(turn):
            return None
        exp = rec.get("expires_turn")
        if exp not in (None, ""):
            try:
                if int(exp) < int(turn):
                    return None
            except (TypeError, ValueError):
                return None
        if holder and str(rec.get("holder_id") or "") != holder:
            return None
        if priv and str(rec.get("privilege") or "") != priv:
            return None
        return rec
    if not holder:
        return None
    matches = list(db.list_active_authorities(int(turn), holder_id=holder))
    if priv:
        matches = [
            m for m in matches if str(m.get("privilege") or "") == priv
        ]
    if len(matches) != 1:
        return None
    return matches[0]

def _person_ids_from_extract_result(result: Dict[str, Any]) -> List[str]:
    """单条/批抽结果中的人物键（character_id + delegator_id/delegator，保序去重）。

    除名闸 prior/new 同键空间：委派人与主办/协办同属人物参与侧，漏收会把
    「毕自」→「毕自严」的委派人自愈误判 removal_only，或丢合法委派人不触发
    lost_prior_valid。raw `delegator` 与 `delegator_id` 同收（与 normalize 接缝一致）。
    """
    ids: List[str] = []

    def _absorb(roster: Any) -> None:
        if not isinstance(roster, list):
            return
        for item in roster:
            if not isinstance(item, dict):
                continue
            for key in ("character_id", "delegator_id", "delegator"):
                cid = str(item.get(key) or "").strip()
                if cid and cid not in ids:
                    ids.append(cid)

    if "participant_roster" in result:
        _absorb(result.get("participant_roster"))
    for draft in result.get("drafts") or []:
        if isinstance(draft, dict) and "participant_roster" in draft:
            _absorb(draft.get("participant_roster"))
    return ids

def _normalize_participant_roster(
    participants: Iterable[object] | str | None, *, strict_structured: bool = False,
) -> List[Dict[str, object]]:
    """Normalize ADR 0053 entries while retaining explicit legacy string input."""
    values = [participants] if isinstance(participants, str) else list(participants or [])
    roster: List[Dict[str, object]] = []
    for value in values:
        if isinstance(value, Mapping):
            if strict_structured:
                character_id = str(value.get("character_id") or "").strip()
                tier_value = value.get("tier")
            else:
                character_id = str(value.get("character_id") or value.get("name") or "").strip()
                tier_value = value.get("tier") if "tier" in value else value.get("档")
            if strict_structured and not character_id:
                raise ValueError("参与人物 character_id 不能为空")
            if strict_structured and tier_value is None:
                raise ValueError("参与人物 tier 必须显式提供")
            tier = str(tier_value or ("" if strict_structured else "知情")).strip()
            raw_role = str(value.get("role") or value.get("职分") or "")
            role = raw_role
            delegator = str(value.get("delegator_id") or value.get("delegator") or "").strip()
        else:
            if strict_structured:
                raise ValueError("结构化参与人名单每项必须为对象")
            character_id, tier, role, delegator = str(value).strip(), "知情", "", ""
        if not character_id:
            continue
        if tier not in PARTICIPANT_TIERS:
            raise ValueError(f"参与人机械档非法：{tier}")
        item = {"character_id": character_id, "tier": tier, "role": role,
                "delegator_id": delegator or None}
        if item not in roster:
            roster.append(item)
    return roster

def get_secret_order(self, order_id: int) -> Optional[Dict[str, object]]:
    """单查一条密令（任意状态），给承办人查进度工具用。不存在返回 None。"""
    r = self.conn.execute(
        "SELECT * FROM secret_orders WHERE id = ?", (int(order_id),)
    ).fetchone()
    if not r:
        return None
    return {
        "id": int(r["id"]), "minister_name": r["minister_name"],
        "title": r["title"], "content": r["content"],
        "status": r["status"], "result": r["result"] or "",
        "sim_note": (r["sim_note"] if "sim_note" in r.keys() else "") or "",
        "turn_issued": int(r["turn_issued"]),
        "due_turn": int(r["due_turn"] if "due_turn" in r.keys() else 0),
        "turn_closed": r["turn_closed"],
    }

def apply_fixed_period_flows(db: GameDB, state: GameState) -> List[Dict[str, object]]:
    """月度财政 tick：固定收支（compute_budget_lines 定额）+ 军饷逐军 + 建筑逐项落账，LLM 推演前完成。"""
    if not getattr(db.conn, "_commit_suspended", False):
        from ming_sim.applier import atomic
        metrics_before = dict(state.metrics)
        try:
            with atomic(db):
                return apply_fixed_period_flows(db, state)
        except _SubstrateHubFixedFlowAbort as exc:
            state.metrics.clear()
            state.metrics.update(metrics_before)
            raise_fixed_period_flow_abort_if_needed(db, state, exc)
            raise
        except BaseException:
            state.metrics.clear()
            state.metrics.update(metrics_before)
            raise

    flows: List[Dict[str, object]] = []

    def _income(account: str, amount: int, category: str, reason: str) -> None:
        if amount <= 0:
            return
        actual = db.record_issue_economy_move(state, account, amount, category, reason)
        flows.append({"dir": "income", "account": account, "amount": actual,
                      "category": category, "reason": reason})

    def _expense(
        account: str, amount: int, category: str, reason: str, *, origin_ref: str = "",
    ) -> None:
        if amount <= 0:
            return
        actual = db.record_issue_economy_move(
            state, account, -amount, category, reason, origin_ref=origin_ref,
        )
        flows.append({"dir": "expense", "account": account, "amount": abs(actual),
                      "category": category, "reason": reason})

    # ── substrate hub 顶层拨付：京运补 + 中央军饷优先占用月初国库 ──
    # substrate_hub 下旧「户部直扣国库发饷」全局路径退役；省份额由 province substrate，
    # 中央份额由 hub/outbound 后续路径承载，避免同一军饷从旧全局路双付。
    pay_source_cutover = db.is_army_pay_source_cutover_enabled()
    if db.is_substrate_hub_fiscal_engine_enabled():
        db._current_month_central_pay_shortfalls = {}
        db._current_month_central_pay_dues = {}
        db._current_month_pay_opening_arrears = {}
        army_rows_raw = db.conn.execute(
            """
            SELECT id, name, manpower, salary_rate, owner_power, arrears, morale, loyalty,
                   pay_source_region, province_pay_share, central_pay_share,
                   province_pay_arrears, central_pay_arrears, is_tusi, self_funded_pay
            FROM armies
            WHERE owner_power = 'ming' AND is_tusi = 0 AND self_funded_pay = 0
              AND central_pay_share > 0
            """
        ).fetchall()
        try:
            for row in army_rows_raw:
                db._validate_pay_source_values(
                    str(row["id"]), str(row["owner_power"]), str(row["pay_source_region"]),
                    float(row["province_pay_share"] or 0), float(row["central_pay_share"] or 0),
                    bool(row["is_tusi"]), bool(row["self_funded_pay"]),
                    float(row["province_pay_arrears"] or 0), float(row["central_pay_arrears"] or 0),
                )
        except ValueError as exc:
            raise _SubstrateHubFixedFlowAbort(
                f"substrate_hub 军饷饷源校验失败：{exc}"
            ) from exc
        army_map = {str(r["id"]): r for r in army_rows_raw}
        ordered = [army_map[k] for k in ARMY_SALARY_PRIORITY if k in army_map]
        ordered += [r for r in army_rows_raw if str(r["id"]) not in ARMY_SALARY_PRIORITY]
        central_due_by_army, central_haircut_exempt_by_army = _central_dues_with_haircut(
            db, state, ordered,
        )
        try:
            hub_outbound = _compute_substrate_hub_outbound(
                db,
                max(0.0, float(state.metrics.get("国库", 0) or 0)),
                central_due_by_army,
            )

def _region_noop_error(region_id: str, row: sqlite3.Row, raw_field: object, value: object) -> str:
    field = REGION_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
    if field == "reason":
        return ""
    if field == "cannon":
        delta = int(value)
        cap = int(row["city_level"]) * 8
        old_value = int(row["cannon"])
        if max(0, min(cap, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in FISCAL_SCORE_FIELDS:
        fiscal = json.loads(str(row["fiscal"] or "{}"))
        old_value = int(fiscal.get(field, 50))
        delta = int(value)
        net_pct = int(((legacy_mods.get("regions") or {})
                       .get(region_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_SCORE_FIELDS:
        old_value = int(row[field])
        delta = int(value)
        net_pct = int(((legacy_mods.get("regions") or {})
                       .get(region_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_QUANTITY_FIELDS:
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_TEXT_FIELDS:
        return ""
    return ""

def read_beyond_intent_raw(item: object) -> object:
    """#1260 旨外别名读取单源：真源=ITEM_FIELD_ALIASES 中映射到 beyond_intent 的键。

    返回第一个在场别名的原值；皆无 → None。不判真假（coerce 归写端/读端）。
    flows 嵌套通道与 due_review 效果行共用，禁再手抄 旨外 子集。
    """
    if not isinstance(item, Mapping):
        return None
    # 稳定顺序：canonical 键优先，其余按别名表声明序。
    aliases = [
        key for key, canon in ITEM_FIELD_ALIASES.items()
        if canon == "beyond_intent"
    ]
    ordered: List[str] = []
    if "beyond_intent" in aliases:
        ordered.append("beyond_intent")
    for key in aliases:
        if key not in ordered:
            ordered.append(key)
    for key in ordered:
        if key in item:
            return item[key]
    return None

def recognize_audience_command(message: str) -> str:
    """收夜/留侍口令结构化判词（#526）。

    确定性封闭集（COURT_BREAK / AMBIGUOUS_CLOSE / STAY_ATTEND）；引擎不重解析散文。
    不进 ACTION_CLUSTERS；非第二 parser（无自由散文正则启发）。
    无耗时软判——同步直调即可；坏 shape 由 normalize 归一，不在此宽吞异常。
    """
    from ming_sim.constants import (
        AMBIGUOUS_CLOSE_COMMANDS,
        COURT_BREAK_COMMANDS,
        STAY_ATTEND_COMMANDS,
    )

    text = str(message or "").strip()
    if not text:
        return CMD_NONE
    lowered = text.lower()
    if text in STAY_ATTEND_COMMANDS or lowered in STAY_ATTEND_COMMANDS:
        return CMD_STAY_ATTEND
    if lowered in COURT_BREAK_COMMANDS or text in COURT_BREAK_COMMANDS:
        return CMD_CLOSE_NIGHT
    if text in AMBIGUOUS_CLOSE_COMMANDS or lowered in AMBIGUOUS_CLOSE_COMMANDS:
        return CMD_AMBIGUOUS_CLOSE
    return CMD_NONE

