def _apply_punishment_verdict_effect(
    self, state, row, payload, dossier_id, *, content=None,
) -> None:
    """#517：惩处案卷顺颁后的结构化效果（受判类，打回不进此函数）。"""
    target = str(
        payload.get("target_id") or row.get("target_id") or ""
    ).strip()
    punish_action = str(payload.get("punish_action") or "").strip()
    issue_disposition = str(payload.get("issue_disposition") or "").strip()
    issue_id = int(payload.get("issue_id") or 0)
    issue = None
    if issue_id:
        issue = self.conn.execute(
            "SELECT status,origin_kind,faction_hint,target_roster FROM issues WHERE id=?",
            (issue_id,),
        ).fetchone()
        if issue is None or issue["origin_kind"] != "impeachment_surge":
            raise ValueError("处置所指弹劾潮不存在")
        if issue["status"] != "active":
            return
        if issue_disposition == "办人":
            try:
                roster = json.loads(str(issue["target_roster"] or "[]"))
            except (TypeError, ValueError) as exc:
                raise ValueError("弹劾潮 target_roster 非法") from exc
            if target not in roster:
                raise ValueError("办人目标不在弹劾潮 target_roster")
    if issue_disposition == "压下" and issue is not None:
        faction = str(issue["faction_hint"] or "").strip()
        if self._record_decree_cost(
            dossier_id, state.turn, "authority", "metric", "皇威", -1,
            "压下弹劾", cost_identity="impeachment_suppression",
        ):
            state.metrics["皇威"] = max(0, int(state.metrics.get("皇威", 0)) - 1)
            self.conn.execute(
                "INSERT INTO metrics(key,value) VALUES('皇威',?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                (state.metrics["皇威"],),
            )
        if faction and self._record_decree_cost(
            dossier_id, state.turn, "satisfaction", "faction", faction, -1,
            "压下弹劾", cost_identity="impeachment_suppression",
        ):
            self.adjust_factions({faction: {"satisfaction": -1}}, commit=False)
        self.close_issue(state, issue_id, reason="resolved", commit=False)
        return
    if not target:
        raise ValueError("惩处案卷缺少 canonical target")
    origin_ref = f"dossier:{int(dossier_id)}"
    reason = str(
        payload.get("text") or row.get("decree_text") or punish_action
    )
    # #658：typed backing 单权威（与 stage 首写共吃）
    backing_id = int(require_backing_dossier_id(self, payload.get("backing_dossier_id")) or 0)
    status_by_action = {
        "拿问下狱": "imprisoned",
        "拿问去职": "imprisoned",
        "赐死": "dead",
        "流放": "exiled",
        "削籍": "dismissed",
    }
    if punish_action in status_by_action:
        item = {
            "name": target,
            "origin_ref": origin_ref,
            "动作": "处置",
            "status": status_by_action[punish_action],
            "reason": reason,
        }
        if punish_action == "削籍":
            item["reason_code"] = "获罪削籍"
            item["reason"] = "获罪削籍"
        from ming_sim.issues import _apply_person_changes
        results = _apply_person_changes(
            self,
            state,
            [item],
            content=content,
            origin_ref=origin_ref,
            require_origin=True,

def record_dossier_execution(
    self, dossier_id: int, outcome: str, note: str, turn: int, *,
    close: bool = True, commit: bool = True,
) -> None:
    row = self.get_decree_dossier(dossier_id)
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    outcome = str(outcome or "").strip()
    if outcome not in self._DOSSIER_EXECUTION_OUTCOMES:
        raise ValueError(f"执行 outcome 非法：{outcome}")
    if outcome == "executing" and close:
        raise ValueError("executing 是非终态，必须以 close=False 记录")
    immediate = (
        row["status"] == "promulgated"
        and not self._dossier_has_execution_surface(
            row["action_type"],
            json.loads(str(row.get("payload_json") or "{}")),
        )
    )
    if row["status"] != "executing" and not immediate:
        raise ValueError("执行格只能写入 executing 或无判定面已颁案卷")
    self.conn.execute(
        """
        UPDATE decree_dossiers
        SET execution_outcome=?,execution_note=?,closed_turn=?,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (
            outcome, str(note or ""),
            0 if outcome == "executing" else int(turn),
            int(dossier_id),
        ),
    )
    if close:
        self.close_decree_dossier(
            dossier_id,
            str(note or "") if outcome == "failed" else "",
            commit=False,
        )
    # #625：走样/变形/烂尾终值 → 空子暴露（与对账路统一：本 turn 稽核在场门）
    if outcome in {"degraded", "transformed", "failed"}:
        action_type = str(row.get("action_type") or "").strip()
        if (
            action_type in DOSSIER_ACTION_TYPES
            and self.dossier_has_supervision_presence(int(dossier_id), int(turn))
        ):
            self.record_loophole_exposure(
                int(dossier_id), int(turn), action_type, outcome,
                commit=False,
            )
    self._commit_dossier_write(commit)

def _army_noop_error(army_id: str, row: sqlite3.Row, raw_field: object, value: object) -> str:
    field = ARMY_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
    if field == "reason":
        return ""
    # #319：latched 静默 no-op 与写缝同口径——战略信封预检须拒整封，不得半落兄弟结果。
    # loyalty 不进此函数：caller 对 field=="loyalty" 先 continue，再走
    # fold_loyalty_alias_delta + latched_army_field_effect_permitted +
    # compute_loyalty_soft_adjust；勿在此再堆 loyalty 专属预测（死分支）。
    if bool(row["is_mutinied"]):
        if field == "manpower":
            if not latched_army_field_effect_permitted(field, value):
                return _noop_error("army", army_id, raw_field, value)
        else:
            return _noop_error("army", army_id, raw_field, value)
    if field == "cannon_equipment":
        old_value = int(row[field])
        if max(0, min(12, old_value + int(value))) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field == "arrears":
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_SCORE_FIELDS:
        old_value = int(row[field])
        delta = int(value)
        net_pct = int(((legacy_mods.get("armies") or {})
                       .get(army_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_QUANTITY_FIELDS:
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_TEXT_FIELDS:
        return ""
    return ""

def _character_gazette_rows(public_events: Sequence[dict]) -> list[dict[str, object]]:
    """Person gazette rows come only from that person's typed public projection.

    Raw ``turn_reports`` aggregates are not an authorization boundary (#883 / #1832).
    """
    rows: list[dict[str, object]] = []
    for item in public_events or []:
        source_id = str(item.get("source_id") or "")
        if not (
            source_id.startswith("projection:turn_report:")
            or (source_id.startswith("turn_report:") and source_id.endswith(":public"))
        ):
            continue
        body = str(item.get("body") or "")
        if not body.strip():
            continue
        rows.append({
            "year": int(item.get("year") or 0),
            "period": int(item.get("period") or 0),
            "turn": int(item.get("turn") or 0),
            "body": body,
        })
    return rows

def _render_field_specs(
    specs: Sequence[Tuple[str, FieldSpec]],
) -> Tuple[List[str], List[str]]:
    """Render transport examples and action-scoped constraints from catalog rows."""
    lines: List[str] = []
    notes: List[str] = []
    seen_zh: set = set()
    for action, spec in specs:
        prefix = f"{action}·" if action else ""
        if spec.allowed is not None:
            values = sorted(spec.allowed, key=lambda value: (value != "无", value))
            example = f'"{"|".join(values)}"'
        elif spec.as_int:
            example = "null" if spec.default is None else "0"
            if spec.int_lo > 0 or spec.quantity_unit:
                constraint = (
                    f"可null；命中 JSON integer>={spec.int_lo}；禁数字字符串"
                    if spec.default is None
                    else f"JSON integer>={spec.int_lo}"
                )
                if spec.quantity_unit:
                    constraint += f"；单位={spec.quantity_unit}"
                notes.append(f"{prefix}{spec.zh}：{constraint}")
        else:
            example = '""'
        if spec.zh not in seen_zh:
            seen_zh.add(spec.zh)
            lines.append(f'  "{spec.zh}": {example},')
        if spec.populated_when is not None:
            controller_name, controller_values = spec.populated_when
            controller = _field_specs()[controller_name]
            values = "|".join(sorted(controller_values))
            notes.append(
                f"{prefix}{spec.zh}：仅{controller.zh}={values}时填写；其它留空"
            )
    return lines, notes

