def _effect_extraction_from_clean(
    clean: Mapping[str, object],
    event_id: str,
    *,
    empty_extraction: Mapping[str, object],
) -> tuple[dict[str, object], dict[str, list[tuple[str, object]]], dict[str, list[str]], list[dict[str, object]]]:
    """Build one apply_score_extraction payload from a single effect envelope."""
    extraction = copy.deepcopy(dict(empty_extraction))
    ordered_deltas = {field: [] for field in _ORDERED_DELTA_FIELDS}
    ordered_effect_event_ids = {field: [] for field in empty_extraction}
    unowned_outcomes: list[dict[str, object]] = []
    for field, value in clean.items():
        if field not in empty_extraction:
            continue
        if isinstance(value, list):
            extraction[field].extend(value)
            ordered_effect_event_ids[field].extend([event_id] * len(value))
        elif isinstance(value, dict):
            if field == "事件结局":
                from ming_sim.issues import _merge_first_event_outcome
                unowned_outcomes.extend(
                    _merge_first_event_outcome(extraction[field], value, event_id)
                )
            else:
                extraction[field].update(value)
            if field in ordered_deltas:
                ordered_deltas[field].extend(value.items())
                ordered_effect_event_ids[field].extend([event_id] * len(value))
        elif value is not None:
            extraction[field] = value
    return extraction, ordered_deltas, ordered_effect_event_ids, unowned_outcomes

def bake_distance_matrix(graph: Mapping[str, object]) -> dict[str, dict[str, float | int]]:
    """Bake all-pairs shortest travel times from a weighted region graph.

    Node weights are the cost of crossing a region.  The first and last node
    count half, while intermediate nodes count in full.  A node-to-itself
    route is explicitly zero because the graph is province-granularity data.
    """

    raw_nodes = graph.get("nodes")
    if not isinstance(raw_nodes, Mapping) or not raw_nodes:
        raise ValueError("distance graph must contain a non-empty nodes object")
    node_weights = {
        node: _number(config.get("weight") if isinstance(config, Mapping) else None, f"nodes.{node}.weight")
        for node, config in raw_nodes.items()
        if isinstance(node, str)
    }
    if len(node_weights) != len(raw_nodes):
        raise ValueError("distance graph node ids must be strings")
    adjacency = _graph_edges(graph)
    matrix: dict[str, dict[str, float | int]] = {}

    for source in node_weights:
        distances = {source: 0.0}
        queue: list[tuple[float, str]] = [(0.0, source)]
        while queue:
            cost_so_far, current = heapq.heappop(queue)
            if cost_so_far != distances[current]:
                continue
            for neighbor, edge_cost in adjacency[current]:
                # The source endpoint is half-weighted immediately.  An
                # intermediate node is full-weighted; the destination half is
                # corrected when the candidate is read into the matrix.
                node_cost = node_weights[current] if current != source else node_weights[source] / 2
                candidate = cost_so_far + edge_cost + node_cost
                if neighbor not in distances or candidate < distances[neighbor]:
                    distances[neighbor] = candidate
                    heapq.heappush(queue, (candidate, neighbor))

        row: dict[str, float | int] = {}
        for destination in node_weights:
            if destination == source:
                row[destination] = 0
                continue
            if destination not in distances:
                raise ValueError(f"distance graph is disconnected: {source} -> {destination}")
            row[destination] = distances[destination] + node_weights[destination] / 2
        matrix[source] = row

    # Dijkstra is run once per source, so mathematically identical routes can
    # still accumulate binary floating-point values in a different order.  The
    # asset models an undirected graph: choose one canonical calculation for
    # each pair, normalize it for JSON, then mirror that exact value.
    for source in sorted(node_weights):
        for destination in sorted(node_weights):
            if source >= destination:
                continue
            distance = round(float(matrix[source][destination]), 10)
            matrix[source][destination] = distance
            matrix[destination][source] = distance

    return matrix

def _apply_class_dict(
    db: GameDB,
    class_delta: Dict[str, object],
    *,
    commit: bool = True,
) -> DeltaApplyResult:
    """class_delta 结构：{ '农民@shaanxi': {'satisfaction': -5, 'leverage': +3}, '士绅': {...} }
    key 不带 @ 默认全国汇总。字段只接 satisfaction / leverage 增量。

    逐项拒收契约（ADR 0008 决定 1，#14/#63）：字段值非整数（含 bool/float）→
    invalid_enum 逐项拒收；查无此阶级名由 db.adjust_classes 返 missing_ref。
    #649 §1.4 升格：value 内出现 population 键 → 该 item 整项以 invalid_enum 拒收
    留痕（原为静默忽略；合法转移入口开通后，静默通道不得存活），其余 sat/lev 合法
    item 不受累——一切人口变化走 population_transfers 守恒原语。二级真值非 dict
    （如 {"农民": 0}）同样逐项拒收。
    返回 (已落 delta dict, 拒收项列表)：前者供 web 「阶级变化」面板，后者由顶层置于
    "class_delta_rejections" 段、桥接自动收。
    """
    # #649 C3/C4：字段名先经 ITEM_FIELD_ALIASES 单一真源 canonical 化（满意→satisfaction、
    # 人口→population），使 population guard 对中英文拼写统一整项拒收，不在本层手抄别名分支。
    from ming_sim.simulation import _canonical_item_fields

    cleaned: Dict[str, Dict[str, int]] = {}
    rejected: List[Dict[str, object]] = []
    class_delta = class_delta if isinstance(class_delta, dict) else {}  # #117 同类：真值非 dict 守卫
    for key, fields in class_delta.items():
        if isinstance(fields, dict):
            fields = _canonical_item_fields(fields)
        if not isinstance(fields, dict):
            rejected.append({
                "name": str(key), "rejected": True, "category": "invalid_enum",
                "reason": f"「{key}」阶级变化须为对象：{fields!r}",
                "item": {str(key): fields},
            })
            continue
        if "population" in fields:
            rejected.append({
                "name": str(key), "rejected": True, "category": "invalid_enum",
                "reason": (
                    f"「{key}」class_delta 无 population 更新面：写 population 整项拒收，"
                    "人口只经 population_transfers 守恒转移变动（#649/0087，单记录双写）"
                ),
                "item": {str(key): fields},
            })
            continue
        entry: Dict[str, int] = {}
        for fname in ("satisfaction", "leverage"):
            raw = fields.get(fname)
            if raw is None:
                continue
            try:
                d = _strict_int(raw)
            except (TypeError, ValueError):
                rejected.append(_value_reject(key, raw, fields, fname))
                continue
            if d == 0:
                continue
            entry[fname] = d
        if entry:
            cleaned[str(key)] = entry
    if cleaned:
        # 同 faction：db 层未知名 missing_ref 拒收未写库，从 cleaned 剔除防面板误显（cmr r3 codex）。
        for _rej in db.adjust_classes(cleaned, commit=commit):
            cleaned.pop(str(_rej.get("name", "")), None)
            rejected.append(_rej)
    return DeltaApplyResult(cleaned, rejected)

def _apply_extracted_army_delta(
    db: GameDB, state: GameState, pseudo_event: Event, army_id: str,
    raw_changes: Dict[str, object], *, commit_now: bool,
) -> List[Dict[str, object]]:
    """Apply one extracted army item, including an explicit paired cannon transfer."""
    army_changes: List[Dict[str, object]] = []
    origin_ref = str(raw_changes.get("origin_ref") or "").strip()
    payload = {k: v for k, v in raw_changes.items() if k != "origin_ref"}
    if "cannon_transfer_to" in payload:
        target_id = payload.pop("cannon_transfer_to")
        cannon_keys = [k for k in payload if ARMY_FIELD_ALIASES.get(k, k) == "cannon_equipment"]
        try:
            requested = _strict_int(payload[cannon_keys[0]]) if len(cannon_keys) == 1 else 0
        except (TypeError, ValueError):
            requested = 0
        source = db.conn.execute(
            "SELECT cannon_equipment, is_mutinied FROM armies WHERE id=?", (army_id,)
        ).fetchone()
        origin_error = db.effect_origin_rejection(origin_ref)
        if origin_error:
            army_changes.append({"army_id": army_id, **origin_error,
                                 "item": {"army_id": army_id, "changes": raw_changes}})
            return army_changes
        target = (db.conn.execute(
            "SELECT cannon_equipment, is_mutinied FROM armies WHERE id=?", (target_id,)
        ).fetchone() if isinstance(target_id, str) and target_id else None)
        if (len(cannon_keys) != 1 or requested >= 0 or source is None
                or target is None or target_id == army_id):
            army_changes.append({
                "army_id": army_id, "rejected": True,
                "category": "missing_ref" if source is None or target is None else "invalid_enum",
                "reason": "随军炮转移须指定在册来源、去向及负数拟转量",
                "item": {"army_id": army_id, "changes": raw_changes},
            })
            return army_changes
        for key in cannon_keys:
            payload.pop(key)
        writable = all(
            not bool(row["is_mutinied"]) or latched_army_field_effect_permitted(
                "cannon_equipment", delta,
            )
            for row, delta in ((source, requested), (target, -requested))
        )
        actual = (min(-requested, int(source["cannon_equipment"]),
                      12 - int(target["cannon_equipment"])) if writable else 0)
        if actual > 0:
            db.conn.execute("SAVEPOINT cannon_transfer")
            try:
                transfer_changes: List[Dict[str, object]] = []
                for leg_id, leg_delta in ((army_id, -actual), (target_id, actual)):
                    leg_changes = db.apply_army_deltas(
                        state, pseudo_event, None, "档房",
                        {leg_id: {"随军大炮": leg_delta, "reason": raw_changes.get("reason")}},
                        commit=False, origin_ref=origin_ref, require_origin=True,
                    )
                    if len(leg_changes) != 1 or leg_changes[0].get("delta") != leg_delta:
                        raise RuntimeError("随军炮转移双边实数不等")
                    transfer_changes.extend(leg_changes)
                db.conn.execute("RELEASE SAVEPOINT cannon_transfer")
            except Exception:
                db.conn.execute("ROLLBACK TO SAVEPOINT cannon_transfer")
                db.conn.execute("RELEASE SAVEPOINT cannon_transfer")
                raise
            army_changes.extend(transfer_changes)
            if commit_now:
                db.conn.commit()
        else:
            for leg_id in (army_id, target_id):
                army_changes.append({
                    "army_id": leg_id, "field": "cannon_equipment",
                    "delta": 0, "applied": False, "reason": raw_changes.get("reason"),
                })
    army_changes.extend(db.apply_army_deltas(
        state, pseudo_event, None, "档房", {army_id: payload}, commit=commit_now, origin_ref=origin_ref, require_origin=True,
    ))

    return army_changes

def _gate_passed(gate: Dict[str, str], metrics: Dict[str, int], db: GameDB) -> bool:
    """trigger_gate 全部条件满足才返回 True。条件形如 '<=240'（数值）或 '==ming'（文本相等）。
    key 形式见 _eval_gate_key。gate=None（content JSON 显式 null）视同空门、恒过，不 .items()
    AttributeError 崩候选收集（PR#107 gemini；集中守 None，seed/历史两分支共用此函数同得保护）。
    """
    for key, cond in (gate or {}).items():
        cond = str(cond).strip()  # 非字符串条件值(JSON 漏引号写成 60/True)先 str 强转，不 .strip() 崩（PR#107 gemini）
        # 文本相等 / 枚举：==<word> / !=<word> / in=a|b（RHS 非纯数字）
        sm = re.match(r"^(==|!=|in=)\s*(.+)$", cond)
        if sm and (sm.group(1) == "in=" or not re.match(r"^-?\d+$", sm.group(2).strip())):
            sop, sval = sm.group(1), sm.group(2).strip()
            try:
                cur = _eval_gate_key_str(key, db)
            except sqlite3.OperationalError as exc:
                # typo'd 字段名 → SELECT 绑 SQLite 抛「no such column」；fail-loud 成清晰 content
                # 错误（#12 Q3：trigger_gate 字段错属静态 content schema 错）。其它 DB 错（锁/无表等）
                # 不误标字段，原样上抛（online sourcery）。
                if "no such column" in str(exc).lower():
                    raise ValueError(f"trigger_gate key「{key}」字段无效（DB 无此列）：{exc}") from exc
                raise
            if cur is None:
                return False
            if sop == "==" and cur != sval:
                return False
            if sop == "!=" and cur == sval:
                return False
            if sop == "in=" and cur not in {part.strip() for part in sval.split("|") if part.strip()}:
                return False
            continue
        m = re.match(r"^(>=|<=|>|<|==)\s*(-?\d+)$", cond)
        if not m:
            return False
        op, num = m.group(1), int(m.group(2))
        try:
            val = _eval_gate_key(key, metrics, db)
        except sqlite3.OperationalError as exc:
            if "no such column" in str(exc).lower():
                raise ValueError(f"trigger_gate key「{key}」字段无效（DB 无此列）：{exc}") from exc
            raise  # 其它 DB 错不误标字段（online sourcery）
        if val is None:
            return False
        if op == ">=" and not val >= num:
            return False
        if op == "<=" and not val <= num:
            return False
        if op == ">" and not val > num:
            return False
        if op == "<" and not val < num:
            return False
        if op == "==" and not val == num:
            return False
    return True

def _normalize_event_terminal_reason(ev: Event, raw: object) -> str:
    label = re.sub(r"\s+", "", str(raw or ""))
    if not label:
        return ""
    allowed = getattr(ev, "terminal_reason_labels", []) or []
    for canonical in allowed:
        if label == re.sub(r"\s+", "", canonical):
            return canonical
    return ""

def run_fiscal_levy_pass() -> None:
    terminal_records = _event_terminal_records(db)
    for ev in c.events:
        if getattr(ev, "category", "") != FISCAL_LEVY_EVENT_CATEGORY:
            continue
        if ev.id in terminal_records:
            _canonicalize_existing_fiscal_levy_terminal_reason(
                ev,
                terminal_records[ev.id],
                state,
                db,
            )
        # #1892：三饷是皇帝亲裁，结局**不经本通道**从原始选项标签旁路代批。
        # 终态只由 apply_petition_event_outcome（#1815 单一语义写口）置定；本通道
        # 只做三件事：归一已落终态的标签、按 settle.p 落征收、过窗口者落过期。
        # 「留中」不写终态，因此不进 terminal_records，本循环自然不动它——事件
        # 仍在请旨候选里等下次呈报。
        if ev.id not in terminal_records and _event_window_expired(ev, state):
            db.mark_event_expired(state, ev.id, commit=False)
            terminal_records[ev.id] = {
                "terminal_state": "expired",
                "terminal_reason": "过最晚触发时点仍未达成触发门",
            }
            applied.append({"id": ev.id, "title": ev.title, "terminal_state": "expired"})
    _apply_fiscal_levy_targets(db, state, terminal_records)

def legacy_reasoning_strength(data: Dict[str, object]) -> str:
    candidates = []
    if str(data.get("advanced_model") or "").strip():
        candidates.append(data.get("advanced_thinking_level"))
    candidates.append(data.get("thinking_level"))
    for value in candidates:
        legacy = str(value or "").strip().lower()
        if legacy in {"minimal", "disabled", "none"}:
            return "off"
        strength = normalize_reasoning_strength(legacy)
        if strength:
            return strength
    return ""

def region_aliases(region: Region) -> List[str]:
    aliases = [region.id, region.name, compact_name(region.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", region.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(REGION_SPECIAL_ALIASES.get(region.id, ()))
    unique: List[str] = []
    seen: set = set()
    for alias in aliases:
        key = compact_name(alias)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(alias)
    return unique

def _write_textual_fact_files(
    tmp: Path, db: Any, character: Any, knowledge: dict,
    issue_materials: Sequence[dict[str, object]],
) -> list[str]:
    store = getattr(db, "textual_facts", None)
    readable = getattr(store, "readable_materials", None)
    if not callable(readable):
        return []
    subjects: list[tuple[str, str, str]] = []
    name = str(getattr(character, "name", "") or "")
    if name:
        subjects.append(("character", name, name))
    region_ids = set((knowledge.get("scope") or {}).get("region_ids") or ())
    if region_ids and hasattr(db, "region_rows"):
        for row in db.region_rows():
            if str(row["id"] or "") not in region_ids:
                continue
            rid = str(row["id"] or "")
            rname = str(row["name"] or rid)
            if rid:
                subjects.append(("region", rid, rname))
    army_ids = set((knowledge.get("scope") or {}).get("army_ids") or ())
    if army_ids and hasattr(db, "army_rows"):
        for row in db.army_rows():
            if str(row["id"] or "") not in army_ids:
                continue
            aid = str(row["id"] or "")
            aname = str(row["name"] or aid)
            if aid:
                subjects.append(("army", aid, aname))
    for item in issue_materials:
        affair_id = int(item.get("affair_id") or 0)
        if affair_id > 0:
            subjects.append(("affair", str(affair_id), str(item.get("title") or affair_id)))
    index: list[str] = []
    seen: set[tuple[str, str]] = set()
    for kind, subject_id, label in subjects:
        key = (kind, subject_id)
        if key in seen:
            continue
        seen.add(key)
        facts = readable(subject_kind=kind, subject_id=subject_id)
        if not facts:
            continue
        body = "\n".join(str(fact.body or "") for fact in facts)
        if not body:
            continue
        rel = f"{_FACT_DIR}/{kind}-{_safe_segment(label)}.txt"
        _write_text(tmp / rel, body)
        index.append(rel)
    return index

def format_region_changes(changes: List[Dict[str, object]]) -> str:
    # 拒收项(ADR 0008 决定 1)与 applied 项同列，但不是盘面变化，先滤掉。
    changes = [c for c in (changes or []) if not (isinstance(c, dict) and c.get("rejected"))]
    if not changes:
        return f"本{TURN_UNIT}未见明确地区盘面变化。"
    parts = []
    for change in changes:
        delta = change["delta"]
        if delta is None:
            parts.append(f"{change['region']}{change['label']}改为{change['new']}（{change['reason']}）")
        else:
            sign = "+" if int(delta) > 0 else ""
            parts.append(f"{change['region']}{change['label']}{sign}{int(delta)}（{change['reason']}）")
    return "；".join(parts) + "。"

def declared_report_action_origin(raw: object, *, base: str) -> str:
    """月报 origin 只留下人物已经声明的睁眼闭眼或带私货。

    同派／敌派是监督事实，不是行动。未声明、或声明里夹着别的记号，都不写成行动。
    """
    text = str(raw or "").strip()
    if not text:
        return base
    if text.startswith("dossier-report:"):
        _root, parsed = parse_report_origin(text)
        marks = [mark for mark in parsed if mark in DECLARED_REPORT_ACTION_MARKS]
        return compose_report_origin(base, marks)
    parts = [part.strip() for part in text.split(ORIGIN_MARK_SEP) if part.strip()]
    marks = [part for part in parts if part in DECLARED_REPORT_ACTION_MARKS]
    return compose_report_origin(base, marks)

def _env_from_dotenv() -> None:
    env_path = ROOT / ".env"
    if env_path.exists():
        for line in env_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, value = line.partition("=")
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))
    for src, dst in (
        ("CLI_API_KEY", "OPENAI_API_KEY"),
        ("CLI_BASE_URL", "OPENAI_BASE_URL"),
        ("CLI_MODEL", "OPENAI_MODEL"),
    ):
        if os.environ.get(src) and not os.environ.get(dst):
            os.environ[dst] = os.environ[src]

