def _dedicated_accounts(row: Any) -> List[str]:
    """专款账户读口（真实 producer 可达）：

    1. tags 含「专款:X」——承诺立项 new_issues.tags 既有写口（prompt 钉专款标签）
    2. ongoing_effects.economy[].account——承诺月供账户即专款流向
    """
    accounts: List[str] = []
    seen: Set[str] = set()

    def _add(raw: object) -> None:
        acc = str(raw or "").strip()
        if acc and acc not in seen:
            seen.add(acc)
            accounts.append(acc)

    try:
        keys = row.keys()
    except Exception:
        keys = []

    tags_raw = row["tags"] if "tags" in keys else "[]"
    try:
        tags = json.loads(tags_raw or "[]")
    except (TypeError, ValueError):
        tags = []
    if isinstance(tags, list):
        for tag in tags:
            t = str(tag or "").strip()
            if t.startswith("专款:"):
                _add(t.split(":", 1)[1].strip())

    ongoing_raw = row["ongoing_effects"] if "ongoing_effects" in keys else "{}"
    ongoing = loads_effect_dict(ongoing_raw or "{}")
    economy = ongoing.get("economy") if isinstance(ongoing, dict) else None
    if isinstance(economy, list):
        for item in economy:
            if isinstance(item, dict):
                _add(item.get("account"))
    return accounts

def _grok_effort(reasoning_strength: Optional[str]) -> Optional[str]:
    strength = str(reasoning_strength or "").strip().lower()
    return _GROK_EFFORT_BY_STRENGTH.get(strength)

def _person_grounded_in_source(
    person_id: str,
    source_text: str,
    *,
    db: Any,
    content: Any,
    roster_forms: Optional[Dict[str, List[str]]] = None,
) -> bool:
    """窄确定性同人接地：原文出现该人规范名/别名，或可截断前缀且唯一落此人。

    禁散文关键词/第二套抽取语义；只做名册事实上的子串与前缀机械判定。
    """
    text = str(source_text or "")
    if not text:
        return False
    canon = _canon_person_id_key(person_id, db=db, content=content)
    if not canon:
        return False
    forms_index = roster_forms if roster_forms is not None else _all_roster_identity_forms(
        content=content,
    )
    my_forms = forms_index.get(canon) or _roster_identity_forms(canon, content=content)
    for form in my_forms:
        if form and form in text:
            return True
    # 可截断前缀：form 的真前缀（长≥2）出现在原文，且全名册仅此人的 form 命中该前缀
    for form in my_forms:
        if len(form) <= _MIN_PERSON_PREFIX_LEN:
            continue
        for n in range(_MIN_PERSON_PREFIX_LEN, len(form)):
            prefix = form[:n]
            if prefix not in text:
                continue
            owners: set[str] = set()
            for other_canon, other_forms in forms_index.items():
                for other in other_forms:
                    if other == prefix or other.startswith(prefix):
                        owners.add(other_canon)
                        break
            if owners == {canon}:
                return True
    return False

def normalize_fidelity_state(raw: object) -> Optional[str]:
    text = str(raw or "").strip()
    if not text:
        return None
    if text in _FIDELITY_INDEX:
        return text
    return _FIDELITY_ALIASES.get(text.lower())

def resolve_fulfillment_credit_from_extraction(
    db: Any, state: Any, extracted: Dict[str, object],
) -> List[Dict[str, object]]:
    """dossier_executions outcome=fulfilled → 兑付/撑完。

    消费调用方已滤 rejected 的落格项；本轴不再二次闸（单一保护点在
    apply_score_extraction 的 minus-rejections）。fulfilled 仍以 DB 终值为门。
    """
    if not isinstance(extracted, dict):
        return []
    out: List[Dict[str, object]] = []
    seen: Set[int] = set()
    for it in extracted.get("dossier_executions") or []:
        if not isinstance(it, dict):
            continue
        if str(it.get("outcome") or "").strip() != "fulfilled":
            continue
        try:
            did = int(it.get("dossier_id"))
        except (TypeError, ValueError):
            continue
        if did in seen:
            continue
        seen.add(did)
        out.extend(
            record_fulfillment_credit(
                db, state,
                dossier_id=did,
                context=_narrative_context(it.get("note"), it.get("reason")),
            )
        )
    return out

def _coerce_bool_flag(raw: object) -> bool:
    if isinstance(raw, bool):
        return raw
    if raw is None:
        return False
    if isinstance(raw, (int, float)):
        return raw != 0
    return str(raw).strip().lower() in {"1", "true", "yes", "y", "是", "土司", "自养", "自养军饷"}

def _find_pacification_target(self, content, name: str) -> Optional[str]:
    """Resolve living canonical 内乱 leader still needing 自新受抚 (敌对/潜伏 only)."""
    matched = None
    if name in content.characters:
        matched = name
    else:
        matched = next((
            key for key, character in content.characters.items()
            if name in (character.aliases or [])
        ), None)
    if not matched:
        return None
    row = self.conn.execute(
        "SELECT status, power_id FROM characters WHERE name=?", (matched,),
    ).fetchone()
    if row is None or row["status"] != "active" or row["power_id"] in (None, "ming"):
        return None
    power = self.conn.execute(
        "SELECT kind, leader, stance FROM powers WHERE id=?", (row["power_id"],),
    ).fetchone()
    if power is None or not (
        power["kind"] == "内乱"
        and power["stance"] in {"敌对", "潜伏"}
        and power["leader"] == matched
    ):
        return None
    return matched

def _is_seeded_military_pay_funnel(self, settle: Dict[str, Any]) -> bool:
    meta = settle.get("_meta")
    if not isinstance(meta, dict):
        return False
    postures = meta.get("postures")
    return isinstance(postures, list) and "纯军饷漏斗" in postures

def _normalize_dossier_report_origin(
    cls, origin: object, *, is_terminal: bool = False,
) -> str:
    raw = str(origin or "").strip()
    if not raw:
        return (
            cls.DOSSIER_REPORT_ORIGIN_VERDICT
            if is_terminal
            else cls.DOSSIER_REPORT_ORIGIN_MONTHLY
        )
    prefix = cls.DOSSIER_REPORT_ORIGIN_NS
    if not raw.startswith(prefix) or not raw[len(prefix):].strip():
        raise ValueError("奏报 origin 须带 dossier-report 命名空间前缀")
    return raw

def coerce_beyond_intent_flag(value: object) -> int:
    """闭世界肯定识别器：仅契约内肯定表示 →1；缺席/否定/空/畸形一律 →0。

    肯定：True / 非零 int·float / 肯定串集 {"1","true","yes","on","是","有","真"}。
    开放兜底永不得回归——畸形输入不得捏造肯定标记（0072/0118 真相层）。
    """
    if value is None:
        return 0
    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return 1 if int(value) != 0 else 0
    text = str(value).strip().lower()
    return 1 if text in {"1", "true", "yes", "on", "是", "有", "真"} else 0

def merge_execution_note(
    self, dossier_id: int, fragment: str, *, commit: bool = True,
) -> str:
    """下游说明片段合并写口（#565；S12/#567 消费方）。

    初写仍由 record_dossier_execution 落 judge note；本接口只做增补合并。
    """
    text = str(fragment or "")
    if not text:
        raise ValueError("说明片段不能为空")
    row = self.get_decree_dossier(dossier_id)
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    existing = str(row.get("execution_note") or "")
    if text in existing.split("；"):
        merged = existing
    elif existing:
        merged = f"{existing}；{text}"
    else:
        merged = text
    if merged != existing:
        self.conn.execute(
            """
            UPDATE decree_dossiers
            SET execution_note=?, updated_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (merged, int(dossier_id)),
        )
        self._commit_dossier_write(commit)
    return merged

def _dispatch_effects(
    db: Any,
    state: Any,
    raw: object,
    *,
    night_id: int,
    collector: RejectionCollector,
    turn: int,
    source: Provenance,
    visible_refs: Optional[Mapping[str, object]] = None,
    defer_disclosure: bool = False,
) -> SectionResult:
    """把过月 C0 效果 envelope 交既有月末效果核算口，不复制领域适配器。

    召对夜里的 effects 表示旨意办理结果，仍只是预推候选；当场实况由各自
    section 承接，不能借 effects 绕过 ADR 0157 的过月落账边界。

    #1844：effects 数组按交代先后逐笔落账——后来的效果读到先前实际落账后的
    存量；不按实体段固定类别顺序重排跨类因果。一次 apply 内按旨序交错字段，
    批次性副作用（回流等）仍只核算一次。
    """
    if raw is None or raw == {}:
        return SectionResult(applied=[], rejected=[])
    if int(night_id or 0) > 0:
        return SectionResult(applied=[], rejected=[RejectedItem(
            item={"raw_value": raw}, reason="召对夜不能落旨意办理效果，须待过月核算",
            category="invalid_state", source=source,
        )])
    if not isinstance(raw, Mapping) and not isinstance(raw, list):
        return SectionResult(applied=[], rejected=[RejectedItem(
            item={"raw_value": raw}, reason="effects 须为对象或有序对象数组",
            category="invalid_shape", source=source,
        )])

    from ming_sim.simulation import EMPTY_EXTRACTION
    from ming_sim.issues import (
        _merge_first_event_outcome,
        apply_score_extraction,
        preflight_declared_event_effects,
        sanitize_delta_shape,
    )
    from ming_sim.decree import _collect_inline_rejections
    from ming_sim.person_delta_adapter import normalize_person_changes

    shape_rejections = []
    rejected = []
    has_effect = False
    clean_items = []
    for item in raw if isinstance(raw, list) else [raw]:
        if not isinstance(item, Mapping):
            rejected.append(RejectedItem(
                item={"raw_value": item}, reason="effects 单项须为对象",
                category="invalid_shape", source=source,
            ))
            continue
        has_effect = True
        # 归属是效果 envelope 的声明，不属于旧 extractor delta 的字段。
        event_id = str(item.get("event_id") or "").strip()
        clean, invalid = sanitize_delta_shape({k: v for k, v in item.items() if k != "event_id"})
        shape_rejections.extend(invalid)
        person_changes = normalize_person_changes(clean)
        if person_changes:
            clean["人物变更"] = person_changes
            for field in ("appointments", "character_status_changes", "character_power_changes", "office_changes"):
                clean[field] = []
        clean_items.append((item, event_id, clean))
    if not has_effect:
        return SectionResult(applied=[], rejected=rejected)

    refs = visible_refs or {}
    rejected_events = preflight_declared_event_effects(
        db, state, [(event_id, clean) for _, event_id, clean in clean_items],
        open_affair_ids=set(refs.get("affairs", ())),
    )
    extraction = copy.deepcopy(EMPTY_EXTRACTION)
    ordered_deltas = {field: [] for field in _ORDERED_DELTA_FIELDS}
    ordered_effect_event_ids = {field: [] for field in EMPTY_EXTRACTION}
    effect_sequence: list[tuple[dict[str, object], dict[str, list[tuple[str, object]]], dict[str, list[str]]]] = []
    accepted_effect = False
    accepted_event_ids: list[str] = []

def _validate_promulgation_verdict_item(
    row: object, db: GameDB,
    *,
    proposed_modes: Optional[Dict[int, str]] = None,
    prepared_context: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """The single shape/identity authority for one provider verdict."""
    if not isinstance(row, dict):
        raise LLMContractError("颁布判决须为对象")
    if str(row.get("decision") or "") not in {"promulgated", "rejected"}:
        raise LLMContractError("颁布判决 decision 只能为 promulgated 或 rejected")
    dossier_id = row.get("dossier_id")
    if (isinstance(dossier_id, bool) or not isinstance(dossier_id, int)
            or not 0 < dossier_id <= 2 ** 63 - 1):
        raise LLMContractError("颁布判决 dossier_id 必须为有效 SQLite 正整数")

    context = prepared_context or {}
    if prepared_context is not None:
        faction_names = {
            str(item["name"]) for item in context.get("factions", [])
            if isinstance(item, dict)
        }
        class_names = {str(item) for item in context.get("classes", [])}
        gatekeeper_ids = {
            str(item["name"]) for item in context.get("gatekeepers", [])
            if isinstance(item, dict) and isinstance(item.get("name"), str)
        }
        context_dossiers = {
            int(item["id"]): item for item in context.get("dossiers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), int)
        }
    else:
        faction_names = {
            str(item["name"]) for item in db.conn.execute("SELECT name FROM factions")
        }
        class_names = {
            str(item["name"])
            for item in db.conn.execute("SELECT DISTINCT name FROM classes")
        }
        gatekeeper_ids = {
            str(item["name"])
            for item in db.conn.execute("SELECT name FROM characters")
        }
        context_dossiers = {}

    modes = proposed_modes or {}
    rejection_only_fields = {
        "blocked_layer", "primary_opponents", "gatekeeper_id", "reason",
        "criteria_snapshot", "midzhi_unpromulgatable",
    }
    try:
        decision = row.get("decision")
        mode = modes.get(dossier_id) if isinstance(dossier_id, int) else None
        # Work on a shallow copy: 顺颁 may strip LLM noise without mutating caller input.
        item: Dict[str, object] = dict(row)
        if decision == "promulgated":
            # #1397 / r6: 颁布判官 LLM 常在 decision=promulgated 上夹带打回形解释字段
            # （reason/gatekeeper_id/primary_opponents/criteria_snapshot 等）。decision 已
            # 钉顺颁，这些字段是产出噪声而非语义；硬拒会在 pre_settle 落 settling 后
            # SettlementAbort 卡死整月。剥离已知噪声， downstream 按干净顺颁继续。
            # 真正未知键与打回契约仍硬拒（见下方 exact-key / rejection 校验）。
            for key in rejection_only_fields:
                item.pop(key, None)
            item.pop("legal_reason_code", None)
            # ordinary/midzhi 顺颁均省略 affected_parties（#657 §C.8 later-wins：中旨不猜派）。
            item.pop("affected_parties", None)
        elif mode == "midzhi" and decision == "rejected":
            # 中旨打回：剥离猜派字段；正式离心归 M12。
            item.pop("affected_parties", None)
        marker = item.get("midzhi_unpromulgatable", False)
        if not isinstance(marker, bool):
            raise ValueError("中旨亦不可颁标记必须为 bool")
        if marker:
            if mode is not None:
                if decision != "rejected" or mode != "midzhi":
                    raise ValueError("中旨亦不可颁只能标记中旨打回判决")
            elif decision != "rejected":
                raise ValueError("中旨亦不可颁只能标记打回判决")
        if any(isinstance(key, str) and key.startswith("resistance_") for key in item):
            raise ValueError("颁布判决不得携带阻力数值字段")

def normalize_audience_entry_kind(entry_kind: object) -> str:
    text = str(entry_kind or ENTRY_KIND_STAGED).strip()
    return text or ENTRY_KIND_STAGED

def pointing_at(
    self,
    origin_refs: Iterable[str],
    *,
    subject_kind: str | None = None,
) -> tuple[TextualFact, ...]:
    refs = [str(ref).strip() for ref in origin_refs if str(ref).strip()]
    if not refs:
        return ()
    placeholders = ",".join("?" for _ in refs)
    sql = (
        "SELECT id, subject_kind, subject_id, year, period, turn, body, origin_ref "
        "FROM textual_facts WHERE origin_ref IN (" + placeholders + ")"
    )
    params: list[object] = list(refs)
    if subject_kind is not None:
        kind = str(subject_kind or "").strip()
        if kind not in TEXTUAL_FACT_SUBJECT_KINDS:
            raise ValueError(
                f"textual fact subject_kind must be one of {sorted(TEXTUAL_FACT_SUBJECT_KINDS)}"
            )
        sql += " AND subject_kind = ?"
        params.append(kind)
    sql += " ORDER BY year ASC, period ASC, id ASC"
    return tuple(_row_to_fact(row) for row in self._conn.execute(sql, params).fetchall())

def classify_execution_coverage(
    action_type: object, payload: Optional[Mapping[str, object]] = None,
) -> Optional[str]:
    """只读 canonical 动作及结构化细类判别执行覆盖域，不解析旨文。"""
    action = str(action_type or "").strip()
    if action in _COVERAGE_APPOINTMENT:
        return "appointment"
    if action in _COVERAGE_MULTI_MONTH:
        return "multi_month"
    if action == "punishment":
        from ming_sim.action_clusters import cluster_by_kind

        punish_action = str((payload or {}).get("punish_action") or "").strip()
        cluster = cluster_by_kind("punishment")
        field = next((f for f in cluster.fields if f.name == "punish_action"), None) if cluster else None
        if field is not None and field.execution_coverage is not None:
            return field.execution_coverage.get(punish_action)
    return None

def settle_tick(
    st: Dict[str, Any], p: Dict[str, Any], actions: List[Dict[str, Any]]
) -> FiscalTickResult:
    """单省单月财政 tick。st=开账(CASH/CLAIM/官民田/隐田)，p=本月参数(率/额/Due)，
    actions=本月动作(玩家旨意/事件灌入)。返回新末态 + 流水分解；坏输入/守恒破一律 raise。"""
    # ── 容器型验形（最前置）：st/p 非 dict、actions 非 list/tuple → ValueError，否则下方
    #    `sk in st` / `rq in p` / `for a in actions` 抛 TypeError 逃逸调用方隔离（cmr R3 concur）──
    if not isinstance(st, dict):
        raise ValueError("st 非字典")
    if not isinstance(p, dict):
        raise ValueError("p 非字典")
    if not isinstance(actions, (list, tuple)):
        raise ValueError("actions 非 list/tuple")
    # ── 必填参数 presence（缺省不默认 0——火耗率缺省成 0 = 静默改经济学）──
    for rq in ("三饷应征", "火耗率", "逋赋率", "起运定额", "Due"):
        if rq not in p:
            raise ValueError(f"param {rq} 缺失")
    # ── 开账 stock 全面验形（前置于下方 float 构造：float([]) 等非数值会 TypeError 早于守门、
    #    逃逸调用方 (ValueError/守恒破) 隔离炸 pre_settle，cmr ship-pre R1/R2；CLAIM 也拦——
    #    负军饷欠→偿还环凭空生钱）──
    for sk in (*CASH_KEYS, *CLAIM_KEYS, "官民田", "隐田"):
        if sk in st and st[sk] is None:
            raise ValueError(f"开账 stock {sk} 为 None")
        _sraw = st.get(sk, 0)
        if isinstance(_sraw, bool) or not isinstance(_sraw, (int, float)):
            raise ValueError(f"开账 stock {sk} 非数值")
        if not math.isfinite(float(_sraw)):
            raise ValueError(f"开账 stock {sk} 非有限值(NaN/inf)")
        if float(_sraw) < 0:
            raise ValueError(f"开账 stock {sk} 为负")

    cash = {k: float(st.get(k, 0)) for k in CASH_KEYS}
    claim = {k: float(st.get(k, 0)) for k in CLAIM_KEYS}
    官民田 = float(st.get("官民田", 0))
    隐田 = float(st.get("隐田", 0))
    地0 = 官民田 + 隐田  # 土地守恒锚：清丈只重分类，总亩数不变
    cash0 = sum(cash.values())
    C0 = {k: cash[k] for k in CASH_KEYS if k.startswith("C_")}
    claim0 = dict(claim)
    cash_in = cash_out = 0.0
    # Due 在任何折算消费前验形，避免坏容器先逃成 TypeError/AttributeError。
    _due = p["Due"]
    if isinstance(_due, bool) or not isinstance(_due, dict):
        raise ValueError("Due 非字典")
    for hk, dv in _due.items():
        if hk not in _DUE_KEYS:
            raise ValueError(f"Due 含未知科目 {hk}")
        if isinstance(dv, bool) or not isinstance(dv, (int, float)):
            raise ValueError(f"Due[{hk}] 非数值")
        if not math.isfinite(float(dv)):
            raise ValueError(f"Due[{hk}] 非有限值(NaN/inf)")
        if float(dv) < 0:
            raise ValueError(f"Due[{hk}] 为负")

    # ── #653 偿还序 override ＋ Due 折发系数（ADR 0090）：缺省=祖制默认序、无折 ──
    due_order = _resolve_order_param(p, "due_order", _DUE_KEYS)
    arrears_order = _resolve_order_param(p, "arrears_order", _ARREARS_KEYS)
    _haircut_bp = _resolve_haircut_param(p)  # 验形 fail-loud；实际折算走 _effective_dues
    eff_due = _effective_dues(p)

    r: Dict[str, Any] = dict(
        实征=0, 火耗实收=0, 清欠=0, 拨付gross=0, 起运到京=0, 实付=0, 偿旧欠=0, 行政补饷=0,
        漂没=0, 中饱=0, 民欠新增=0, 蠲免=0, unmet_relief=0,
        NewDebt={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        Repaid={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        action还={"军饷欠": 0},
        # #653 流水分解新字段：per-科目实付分账（TSV 断言实付序）＋折发免除额
        实付分账={h: 0.0 for h in _DUE_KEYS},
        **{f"haircut_{h}": _raw_due(p, h) - eff_due[h] for h in _DUE_KEYS},
    )

    def xfer_internal(frm: str, to: str, amount: float, eff: float = 1.0) -> float:
        """CASH 内部 3-way 转移：source 减 = target 增 + C_eff损耗 增。"""
        actual = min(amount, cash[frm])
        cash[frm] -= actual
        got = actual * eff
        loss = actual * (1 - eff)
        cash[to] += got
        if loss > 0:
            cash["C_eff损耗"] += loss

def _fiscal_levy_liao_seed(meta: Dict[str, object], p: Dict[str, object], region_id: str) -> float:
    if _SETTLE_META_LIAO_SEED_KEY in meta:
        return _as_float(
            meta[_SETTLE_META_LIAO_SEED_KEY],
            ctx=f"{region_id}.settle._meta.{_SETTLE_META_LIAO_SEED_KEY}",
        )
