        if int(entry.get("source_chat_turn_id") or 0) not in secret_turn_ids
    ]

def _write_world_textual_fact_files(
    tmp: Path, db: Any, include_fact: Any = None,
) -> list[str]:
    """World directory: character/army/region textual facts once from store.

    affair facts already ride 事务/*/当前情况.txt — do not mint a second carrier.
    """
    store = getattr(db, "textual_facts", None)
    if store is None or not hasattr(db, "conn"):
        return []
    rows = db.conn.execute(
        "SELECT DISTINCT subject_kind, subject_id FROM textual_facts "
        "WHERE subject_kind IN ('character', 'army', 'region') "
        "ORDER BY subject_kind, subject_id"
    ).fetchall()
    index: list[str] = []
    for row in rows:
        kind = str(row["subject_kind"] or "").strip()
        subject_id = str(row["subject_id"] or "").strip()
        if not kind or not subject_id:
            continue
        facts = store.readable_materials(subject_kind=kind, subject_id=subject_id)
        body = "\n".join(
            str(fact.body or "")
            for fact in facts
            if _keep_fact(fact, include_fact)
        )
        if not body:
            continue
        label = subject_id
        if kind == "region" and hasattr(db, "region_rows"):
            for region in db.region_rows():
                if str(region["id"] or "") == subject_id:
                    label = str(region["name"] or subject_id)
                    break
        elif kind == "army" and hasattr(db, "army_rows"):
            for army in db.army_rows():
                if str(army["id"] or "") == subject_id:
                    label = str(army["name"] or subject_id)
                    break
        rel = f"{_FACT_DIR}/{kind}-{_safe_segment(label)}.txt"
        _write_text(tmp / rel, body)
        index.append(rel)
    return index

def _faction_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, dict):
        return False
    for value in raw.values():
        if isinstance(value, dict):
            if any(
                field in ("satisfaction", "leverage") and _nonzero_int(delta)
                for field, delta in value.items()
            ):
                return True
        elif _nonzero_int(value):
            return True
    return False

def bind_origin_round(origin: Any, turn: int) -> tuple[str, int]:
    text = str(origin or "").strip()
    if not text:
        raise ValueError("边事件 origin 不能为空")
    match = _ROUND_RE.search(text) or _TURN_RE.search(text)
    if match:
        return text, int(match.group(1))
    round_no = int(turn)
    return f"{text}|round:{round_no}", round_no

def _memorial(item: dict, actor: dict) -> dict:
    if not isinstance(item, dict) or not all(isinstance(item.get(k), str) for k in ("title", "context")):
        raise LLMContractError("票拟须提供奏折标题及全文")
    options = item.get("options")
    if not isinstance(options, list) or any(
        not isinstance(o, dict) or not isinstance(o.get("label"), str)
        or not isinstance(o.get("hint", ""), str) for o in options
    ):
        raise LLMContractError("票拟 options 须为拟批与说明的列表")
    return {**item, "actor_name": actor["name"], "actor_office": actor["office"],
            "actor_faction": actor["faction"] or ""}

def prune_auto_saves(saves_dir: str, campaign_id: str, keep_turns: int = AUTO_SAVE_KEEP_TURNS) -> None:
    """清理自动存档：只清同一个 campaign_id，按 turn 分组，绝不碰手动存档。"""
    import os as _os
    import re as _re

    if not _os.path.isdir(saves_dir):
        return
    legacy_auto = _re.compile(rf"^{_re.escape(AUTO_SAVE_PREFIX)}\d{{4}}_\d{{2}}_t\d{{4}}_.+\.db$")
    for f in _os.listdir(saves_dir):
        if legacy_auto.match(f):
            try:
                _os.remove(_os.path.join(saves_dir, f))
            except OSError:
                pass
    campaign_id = (campaign_id or "").strip()
    if not campaign_id:
        return
    buckets: Dict[int, List[str]] = {}
    for f in _os.listdir(saves_dir):
        if not (f.startswith(f"{AUTO_SAVE_PREFIX}{campaign_id}_") and f.endswith(".db")):
            continue
        m = _re.search(r"_t(\d+)_", f)
        if not m:
            continue
        buckets.setdefault(int(m.group(1)), []).append(f)
    keep = max(1, int(keep_turns or 1))
    keep_turn_nums = set(sorted(buckets.keys(), reverse=True)[:keep])
    for turn_num, files in buckets.items():
        if turn_num in keep_turn_nums:
            continue
        for stale in files:
            try:
                _os.remove(_os.path.join(saves_dir, stale))
            except OSError:
                pass

def normalize_commitment_stages(raw: object) -> List[Dict[str, object]]:
    """Normalize structured stages payload → durable list.

    Accepts list/tuple of dicts, or a JSON array string. Non-JSON free text
    returns [] here (读侧宽容面)；写侧由 ``stages_to_json`` 响亮拒绝。

    分段承诺是机械事实（到期判账），只认显式结构化字段。引擎不得从 LLM 自由
    散文正则反推语义（ADR 0142 / 锚定宪法「机器只咬契约，不咬呈现」；owner
    2026-09-30「肯定不能让代码去扣」）。原 ``parse_staged_year_promise`` 的
    中文数词年诺捕获已随该裁定删除，无任何接缝再从散文抠年份。
    """
    if raw in (None, "", [], ()):
        return []
    data = raw
    if isinstance(raw, str):
        text = raw.strip()
        if not text or text in ("[]", "{}"):
            return []
        try:
            data = json.loads(text)
        except (TypeError, ValueError):
            return []
    if not isinstance(data, (list, tuple)):
        return []
    out: List[Dict[str, object]] = []
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            continue
        try:
            due_turn = int(item.get("due_turn") or 0)
        except (TypeError, ValueError):
            continue
        if due_turn <= 0:
            continue
        try:
            stage_idx = int(item.get("stage_idx", idx))
        except (TypeError, ValueError):
            stage_idx = idx
        criterion = str(
            item.get("criterion_text") or item.get("criterion") or ""
        )
        origin_context = str(
            item.get("origin_context") or item.get("origin") or criterion or ""
        )
        if not criterion and origin_context:
            criterion = origin_context
        if not criterion:
            continue
        out.append({
            "stage_idx": stage_idx,
            "due_turn": due_turn,
            "criterion_text": criterion,
            "origin_context": origin_context or criterion,
        })
    out.sort(key=lambda s: (int(s["stage_idx"]), int(s["due_turn"])))
    return out

def compose_report_origin(base: str, marks: Iterable[str] = ()) -> str:
    """结构化 origin：base[+mark...]。base 须已带 dossier-report: 前缀。"""
    cleaned = [str(m).strip() for m in marks if str(m or "").strip()]
    # 去重保序
    seen: Set[str] = set()
    ordered: List[str] = []
    for mark in cleaned:
        if mark in seen:
            continue
        seen.add(mark)
        ordered.append(mark)
    root = str(base or "").strip()
    if not ordered:
        return root
    return root + ORIGIN_MARK_SEP + ORIGIN_MARK_SEP.join(ordered)

def normalize_axis(raw: object) -> str | None:
    text = str(raw or "").strip()
    if text in CENTRIFUGE_AXES:
        return text
    return None

